  function applyPermission(){if(!root())return;const write=writable();root().querySelectorAll('[data-write]').forEach(el=>el.disabled=!write);root().querySelectorAll('[data-upload]').forEach(el=>el.disabled=!write||!can('upload'));root().querySelectorAll('[data-while-idle]').forEach(el=>el.disabled=S.busy);$('saveSession').disabled=!write;$('newSession').disabled=!S.ready||S.busy||!can('create');$('addItem').disabled=!write||!typeOptions().length||S.draft?.items.length>=500;$('addCapacity').disabled=!write||S.draft?.items.length>=500;$('deleteCapacity').disabled=!write||S.kind==='all'||!capacityGroups(S.kind).length;$('openPrint').disabled=!S.ready||S.busy;$('historyOpen').disabled=S.busy;$('historyBottom').disabled=S.busy;$('sessionYear').disabled=!S.ready||S.busy;$('deleteSelected').disabled=!write||!S.checked.size;$('deleteCurrent').disabled=!write||!current();$('selectAll').disabled=!write||!visible().length;$('deleteApply').disabled=!write||!S.deletion?.ids.length;$('batchCriteria').disabled=!write||!visible().length;$('batchApply').disabled=!write||!S.batch?.eligible.length;$('importOpen').disabled=!write||!can('upload');$('newYear').disabled=!S.ready||S.busy||!can('create');$('newYearForm').querySelector('[type=submit]').disabled=!S.ready||S.busy||!can('create');$('prevPage').disabled=S.busy||S.page<=1;$('nextPage').disabled=S.busy||S.page>=Math.ceil(visible().length/50);renderImportSelection();}
  function revokeAll(){S.urls.forEach(URL.revokeObjectURL);S.urls.clear();S.blobs.clear();S.photoLoads.clear();S.files.clear();S.printWindows.forEach(w=>{try{w.close();}catch{}});S.printWindows=[];}
  function resetPrivate(){window.DF_QI_CAL_DOCS?.close();window.DF_QI_CAL_QUERY?.close();S.checked.clear();S.deletion=null;S.batch=null;clearImport();clearCalculations();S.page=1;S.epoch++;S.ready=false;S.busy=false;S.row=null;S.draft=null;S.request=null;S.identity=null;S.client=null;S.history=[];S.capacity=null;S.capacityMemory={};revokeAll();root()?.querySelectorAll('dialog[open]').forEach(x=>x.close());if(root())root().hidden=true;S.active=false;}
  function modified(){S.request=null;$('saveState').textContent='저장 전';$('saveState').parentElement.classList.add('is-dirty');}
  function badge(r){return `<span class="badge ${r.status}">${esc(r.label)}</span>`;}
  function counts(){const results=visible().map(calculate);return {pass:results.filter(r=>r.status==='pass').length,fail:results.filter(r=>r.status==='fail').length,draft:results.filter(r=>r.status==='draft').length};}
  function renderStats(){if(!S.draft)return;const n=counts();$('stats').innerHTML=`<span>적합 <b>${n.pass}</b></span><span>부적합 <b>${n.fail}</b></span><span>미완료 <b>${n.draft}</b></span>`;$('bottomSummary').textContent=`${S.kind==='all'?'전체':S.capacity?S.capacity+' mL':'선택 용량'} ${visible().length}개 · 작성 완료 ${n.pass+n.fail}개`;$('allCount').textContent=S.draft.items.length;}
  function capacityKey(value){const text=String(value??'').trim();if(!/^(?:\d+(?:\.\d*)?|\.\d+)$/.test(text)||!Number.isFinite(Number(text))||Number(text)<=0||Number(text)>10000000)return null;let [whole,fraction='']=text.split('.');whole=(whole||'0').replace(/^0+(?=\d)/,'');fraction=fraction.replace(/0+$/,'');return whole+(fraction?'.'+fraction:'');}
  function capacityGroups(kind=S.kind){const groups=new Map();for(const item of S.draft?.items||[]){if(kind!=='all'&&item.kind!==kind)continue;const key=capacityKey(item.nominal);if(key&&!groups.has(key))groups.set(key,{key,count:0});if(key)groups.get(key).count++;}return [...groups.values()].sort((a,b)=>Number(a.key)-Number(b.key)||a.key.localeCompare(b.key));}
  function syncView(){if(S.kind==='all')S.capacity='all';else{const groups=capacityGroups(),keys=groups.map(x=>x.key),selected=current(),hint=selected?.kind===S.kind?capacityKey(selected.nominal):null;if(!keys.includes(S.capacity))S.capacity=keys.includes(S.capacityMemory[S.kind])?S.capacityMemory[S.kind]:keys.includes(hint)?hint:keys[0]||null;if(S.capacity)S.capacityMemory[S.kind]=S.capacity;}const items=visible();if(!items.some(x=>x.id===S.selected))S.selected=items[0]?.id||null;}
  function visible(){return (S.draft?.items||[]).filter(x=>(S.kind==='all'||x.kind===S.kind&&capacityKey(x.nominal)===S.capacity)&&(!S.query||`${x.name} ${x.code}`.toLowerCase().includes(S.query.toLowerCase())));}
  function renderCapacityTabs(){const groups=capacityGroups();$('capacityTabs').innerHTML=S.kind==='all'?'<button type="button" class="capacity-tab active" role="tab" aria-selected="true" data-capacity="all">전체 용량</button>':groups.map(x=>`<button type="button" class="capacity-tab ${x.key===S.capacity?'active':''}" role="tab" aria-selected="${x.key===S.capacity}" data-capacity="${esc(x.key)}">${esc(x.key)} mL <span>${x.count}</span></button>`).join('')||'<span class="capacity-empty">등록된 용량 없음</span>';}
  function typeOptions(){const options=new Map();for(const item of S.draft?.items||[]){if(S.kind!=='all'&&item.kind!==S.kind)continue;const key=capacityKey(item.nominal);if(!key)continue;const id=item.kind+'|'+key;if(!options.has(id))options.set(id,{id,typeId:item.typeId,name:item.name,kind:item.kind,nominal_ml:key,material:item.material,beta:item.beta,mode:item.mode,tolerance_ml:item.tolerance});}return [...options.values()].sort((a,b)=>a.kind.localeCompare(b.kind,'ko')||Number(a.nominal_ml)-Number(b.nominal_ml));}
  function selectedType(){const selected=typeOptions().find(x=>x.id===$('newType').value);if(!selected)throw Error('초자 종류와 용량을 다시 선택해주세요.');return {...selected,id:selected.typeId||'custom:'+selected.id};}
  function hasSource(item){return ['m1','m2','temp','densityOverride','densityReason','note'].some(key=>String(item[key]??'').trim()!=='')||(item.photos||[]).some(Boolean);}
  function deleteCapacity(){context();if(!writable()||S.kind==='all')return;const key=S.capacity,items=S.draft.items.filter(x=>x.kind===S.kind&&capacityKey(x.nominal)===key);if(!items.length)return;if(items.some(hasSource))throw Error('측정값·비고·사진이 있는 용량은 삭제할 수 없습니다.');if(S.draft.items.length===items.length)throw Error('마지막 용량은 삭제할 수 없습니다.');if(!confirm(`${S.kind} ${key} mL 용량과 빈 초자 ${items.length}개를 이번 일지에서 삭제할까요?`))return;const removed=new Set(items.map(x=>x.id));S.draft.items=S.draft.items.filter(x=>!removed.has(x.id));S.capacity=null;delete S.capacityMemory[S.kind];modified();renderRows();renderDetail();say('');}
  function openCapacity(){context();if(!writable())return;$('capacityForm').reset();$('capacityValue').setCustomValidity('');$('capacityKind').value=S.kind==='all'?(current()?.kind||'부피플라스크'):S.kind;$('capacityDialog').showModal();applyPermission();}
  function addCapacity(event){event.preventDefault();run(()=>{context();if(!writable())return;const form=$('capacityForm');if(!form.reportValidity())return;const kind=$('capacityKind').value,key=capacityKey($('capacityValue').value),material=$('capacityMaterial').value;if(!key){$('capacityValue').setCustomValidity('0보다 크고 10,000,000mL 이하의 용량을 입력해주세요.');$('capacityValue').reportValidity();return;}if(capacityGroups(kind).some(x=>x.key===key)){$('capacityValue').setCustomValidity('이미 등록된 용량입니다.');$('capacityValue').reportValidity();return;}if(!['부피플라스크','피펫','뷰렛','메스실린더'].includes(kind)||!['붕규산유리','소다석회유리','석영유리','기타'].includes(material))throw Error('종류와 재질을 확인해주세요.');const beta=({'붕규산유리':'0.000010','소다석회유리':'0.000025','석영유리':'0.000002'})[material]||'',type={id:'custom:'+kind+':'+key,name:key+' mL '+kind,kind,nominal_ml:key,material,beta,mode:['피펫','뷰렛'].includes(kind)?'출용':'수용',tolerance_ml:null},item=M().newItem(type,S.draft.items);S.draft.items.push(item);S.kind=kind;S.capacity=key;S.capacityMemory[kind]=key;S.selected=item.id;S.query='';$('search').value='';modified();renderRows();renderDetail();$('capacityDialog').close();say('');})();}

  function renderRows(page){if(!S.draft)return;const previous=S.selected;syncView();renderCapacityTabs();const all=visible();S.checked=new Set([...S.checked].filter(id=>all.some(x=>x.id===id)));const pages=Math.max(1,Math.ceil(all.length/50));if(Number.isInteger(page)){S.page=Math.max(1,Math.min(page,pages));S.selected=all[(S.page-1)*50]?.id||null;}else{const index=all.findIndex(x=>x.id===S.selected);S.page=index<0?1:Math.floor(index/50)+1;}const offset=(S.page-1)*50,items=all.slice(offset,offset+50);$('itemsBody').innerHTML=items.map((item,index)=>{const r=calculate(item);return `<tr data-id="${esc(item.id)}" class="${item.id===S.selected?'row-selected':''}" aria-selected="${item.id===S.selected}"><td class="col-select"><input type="checkbox" data-write data-delete-id="${esc(item.id)}" aria-label="${esc(item.name+' '+item.code)} 삭제 항목 선택" ${S.checked.has(item.id)?'checked':''}></td><td class="col-no">${String(offset+index+1).padStart(2,'0')}</td><td><button class="item-cell" data-select="${esc(item.id)}"><span class="item-icon">${svg('flask')}</span><span><strong class="item-name">${esc(item.name)}</strong><small class="item-sub">${esc(item.code)}</small></span></button></td>${['m1','m2','temp'].map(key=>`<td><input class="number-input" data-write type="text" inputmode="decimal" autocomplete="off" data-item="${esc(item.id)}" data-key="${key}" maxlength="24" aria-label="${esc(item.name+' '+item.code+' '+({m1:'M1',m2:'M2',temp:'물 온도'}[key]))}" value="${esc(item[key])}" placeholder="—"></td>`).join('')}<td class="calculated mono" data-result="volume">${fmt(r.volume)}</td><td data-result="badge">${badge(r)}</td></tr>`;}).join('');$('emptyState').hidden=all.length>0;$('visibleCount').textContent=all.length;$('tableCount').textContent=all.length?`${offset+1}–${offset+items.length} / ${all.length}개`:'0개 초자';$('pageInfo').textContent=`${S.page} / ${pages}`;$('prevPage').disabled=S.busy||S.page<=1;$('nextPage').disabled=S.busy||S.page>=pages;root().querySelectorAll('[data-kind]').forEach(x=>{const selected=x.dataset.kind===S.kind;x.classList.toggle('active',selected);x.setAttribute('aria-selected',String(selected));});renderStats();renderDeleteSelection();applyPermission();if(previous!==S.selected)renderDetail();}
  function updateRow(item){const row=$('itemsBody').querySelector(`tr[data-id="${item.id}"]`);if(row){const r=calculate(item);row.querySelector('[data-result="volume"]').textContent=fmt(r.volume);row.querySelector('[data-result="badge"]').innerHTML=badge(r);row.querySelector('.item-sub').textContent=item.code;}scheduleStats();}
  function resultMarkup(item){const r=calculate(item);return `<div class="result-card ${r.status}"><div class="result-label">20℃ 환산부피</div><div class="result-value">${fmt(r.volume)}<span>mL</span></div><div class="result-grid"><div><span>실측오차</span><strong>${fmt(r.error)} <small>mL</small></strong></div><div><span>허용오차</span><strong>${item.tolerance===''?'—':'± '+esc(item.tolerance)} <small>mL</small></strong></div></div></div>`;}
  function refreshResult(){const item=current();if(!item)return;const r=calculate(item);$('detailBadge').innerHTML=badge(r);const card=$('detailInfo').querySelector('.result-card');if(card)card.outerHTML=resultMarkup(item);const density=$('detailInfo').querySelector('[data-density-output]');if(density&&document.activeElement!==density)density.value=item.densityOverride||fmt(r.rho,6);const mass=$('detailInfo').querySelector('[data-mass]');if(mass)mass.textContent=fmt(r.mass);const check=$('criteriaConfirmed');if(check)check.checked=!!item.criteriaConfirmed;const reason=$('densityReasonField');if(reason)reason.hidden=!item.densityOverride;}
  function renderDetail(){const item=current();if(!item){$('detailName').textContent='초자 선택';$('detailBadge').innerHTML='';$('photoCount').textContent='0';$('detailInfo').innerHTML='<div class="empty-state">초자를 선택해주세요.</div>';$('detailPhotos').innerHTML='';return;}$('detailName').textContent=item.name;$('detailBadge').innerHTML=badge(calculate(item));$('detailInfo').innerHTML=`<div class="detail-grid"><div class="field span-2"><label for="qigcDetailCode">관리번호</label><input id="qigcDetailCode" data-write data-detail-field="code" value="${esc(item.code)}" maxlength="60" required></div><div class="field"><label>구분</label><div class="readonly-field">${esc(item.mode)}</div></div><div class="field"><label for="qigcMaterial">재질</label><select id="qigcMaterial" data-write data-detail-field="material">${[...new Set(['붕규산유리','소다석회유리','석영유리','기타',item.material])].map(v=>`<option value="${esc(v)}" ${v===item.material?'selected':''}>${esc(v)}</option>`).join('')}</select></div><div class="field"><label for="qigcDetailBeta">팽창계수</label><input id="qigcDetailBeta" data-write data-detail-field="beta" type="text" inputmode="decimal" maxlength="24" value="${esc(item.beta)}"></div><div class="field"><label for="qigcDetailTolerance">허용오차 <span>mL</span></label><input id="qigcDetailTolerance" data-write data-detail-field="tolerance" type="text" inputmode="decimal" maxlength="24" value="${esc(item.tolerance)}" placeholder="입력"></div><div class="field"><label for="qigcDetailDensity">물의 밀도 <span>g/cm³</span></label><input id="qigcDetailDensity" data-write data-detail-field="densityOverride" data-density-output type="text" inputmode="decimal" maxlength="24" value="${item.densityOverride||fmt(calculate(item).rho,6)}" placeholder="자동"></div><div class="field"><label>수용·출용 질량 <span>g</span></label><div class="readonly-field mono" data-mass>${fmt(calculate(item).mass)}</div></div><div class="field span-2 density-reason" id="qigcDensityReasonField" ${item.densityOverride?'':'hidden'}><label for="qigcDensityReason">밀도 입력 근거</label><input id="qigcDensityReason" data-write data-detail-field="densityReason" maxlength="500" value="${esc(item.densityReason)}" placeholder="근거 입력"></div></div><label class="criteria-check"><input id="qigcCriteriaConfirmed" data-write type="checkbox" ${item.criteriaConfirmed?'checked':''}>재질·팽창계수·허용오차 확인</label>${resultMarkup(item)}<div class="field note-field"><label for="qigcDetailNote">비고</label><textarea id="qigcDetailNote" data-write data-detail-field="note" rows="2" maxlength="1000" placeholder="비고 입력">${esc(item.note)}</textarea></div><div class="detail-bottom"><button class="text-button" id="qigcShowPhotos">${svg('image')}사진 보기</button></div>`;renderPhotos();setDetailTab(S.detailTab);applyPermission();}
  function setDetailTab(tab){S.detailTab=tab;$('detailInfo').hidden=tab!=='info';$('detailPhotos').hidden=tab!=='photos';root().querySelectorAll('[data-detail]').forEach(x=>{const active=x.dataset.detail===tab;x.classList.toggle('active',active);x.setAttribute('aria-selected',String(active));});if(tab==='photos')run(loadVisiblePhotos)();}
  const urlFor=(id,blob)=>{if(!S.urls.has(id))S.urls.set(id,URL.createObjectURL(blob));return S.urls.get(id);};
  const sha=async blob=>Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',await blob.arrayBuffer())),x=>x.toString(16).padStart(2,'0')).join('');
  async function photoBlob(meta,token=stamp()){context(token);if(S.blobs.has(meta.id))return S.blobs.get(meta.id);if(S.photoLoads.has(meta.id))return S.photoLoads.get(meta.id);const task=(async()=>{const blob=await result(context(token).storage.from(BUCKET).download(meta.path));context(token);if(blob.size!==Number(meta.size)||await sha(blob)!==meta.sha256)throw Error('보관 사진 원본 확인에 실패했습니다.');context(token);const typed=blob.type===meta.mime?blob:new Blob([blob],{type:meta.mime});S.blobs.set(meta.id,typed);return typed;})();S.photoLoads.set(meta.id,task);try{return await task;}finally{S.photoLoads.delete(meta.id);}}
  function renderPhotos(){const item=current();if(!item)return;$('photoCount').textContent=item.photos.filter(Boolean).length;$('detailPhotos').innerHTML=`<div class="upload-grid">${['측정 전','측정 후'].map((caption,index)=>{const meta=item.photos[index],blob=meta&&S.blobs.get(meta.id);return `<div class="photo-column"><div class="upload-caption"><span class="photo-step">${String(index+1).padStart(2,'0')}</span>${caption}</div><div class="upload-slot ${meta?'has-image':''}" data-slot="${index}"><input class="sr-only" data-df-drop="off" data-upload data-write type="file" accept="image/jpeg,image/png,image/webp,image/avif" id="qigcPhotoFile${index}" data-file="${index}" aria-label="${caption} 사진 업로드">${meta?(blob?`<button class="photo-open" data-photo-open="${index}" aria-label="${caption} 사진 확대"><img src="${urlFor(meta.id,blob)}" alt="${esc(item.name+' '+caption)}"></button>`:`<button class="upload-placeholder" data-photo-load="${index}" aria-label="${caption} 사진 불러오기">${svg('image')}<strong>사진 불러오기</strong></button>`)+`<button class="remove-image" data-write data-photo-remove="${index}" aria-label="${caption} 사진 삭제">${svg('x')}</button>`:`<button class="upload-placeholder" data-upload data-write data-photo-add="${index}" aria-label="${caption} 사진 선택">${svg('image')}<strong>사진 추가</strong><span>끌어다 놓기</span></button>`}</div>${meta?`<button class="text-button photo-change" data-upload data-write data-photo-add="${index}">사진 변경</button>`:''}</div>`;}).join('')}</div>`;applyPermission();}
  async function loadVisiblePhotos(){const item=current();if(!item||S.detailTab!=='photos')return;const id=item.id,token=stamp();const results=await Promise.allSettled(item.photos.filter(meta=>meta&&!S.blobs.has(meta.id)).map(meta=>photoBlob(meta,token)));context(token);if(current()?.id!==id||S.detailTab!=='photos')return;renderPhotos();const failure=results.find(x=>x.status==='rejected');if(failure)error(failure.reason);}
  function selectItem(id){if(S.busy||!S.draft.items.some(x=>x.id===id))return;S.selected=id;$('itemsBody').querySelectorAll('tr').forEach(row=>{const active=row.dataset.id===id;row.classList.toggle('row-selected',active);row.setAttribute('aria-selected',String(active));});renderDetail();}
  function header(){window.DF_QPF_FORMS.state.view='qi-calibration';const title=document.getElementById('dfDocTitle'),desc=document.getElementById('dfDocDescription'),back=document.getElementById('dfDocBack');if(title)title.textContent=CODE+' (00) 초자내부교정일지';if(desc)desc.textContent='';if(back)back.textContent='← 작성용 품질문서';}
  function render(){if(!S.draft)return;renderYearOptions();for(const [id,key] of [['operator','operator'],['reviewer','reviewer'],['balance','balance_code'],['thermometer','thermometer_code']])$(id).value=S.draft[key]||'';$('saveState').textContent=dirty()?'저장 전':S.row?'저장됨 '+new Intl.DateTimeFormat('ko-KR',{timeZone:'Asia/Seoul',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(S.row.updated_at)):'새 교정';$('saveState').parentElement.classList.toggle('is-dirty',dirty());if(!current())S.selected=S.draft.items[0]?.id;renderRows();renderDetail();header();applyPermission();}
  function renderYearOptions(){const currentYear=new Date().getFullYear(),years=new Set(S.history.map(annualYear));if(S.draft)years.add(annualYear(S.draft));if(can('create'))for(let year=currentYear-5;year<=currentYear+1;year++)years.add(year);$('sessionYear').innerHTML=[...years].sort((a,b)=>b-a).map(year=>`<option value="${year}">${year}년</option>`).join('');$('sessionYear').value=String(annualYear(S.draft));}
  function fresh(items,year=S.year||new Date().getFullYear()){const data=M().createSession(items?{items}:{});return {id:uid(),calibration_year:year,calibration_date:year+'-01-01',calibration_end_date:year+'-12-31',operator:data.operator||'',reviewer:data.reviewer||'',balance_code:data.balance_code||data.balance||'',thermometer_code:data.thermometer_code||data.thermometer||'',items:data.items.map(item=>({...item,calibration_date:''})),criteria:data.criteria||D().criteria};}
  function accept(row){S.checked.clear();S.deletion=null;clearCalculations();const selected=S.draft?.id===row?.id?S.selected:null;if(!row?.id||!Array.isArray(row.data?.items)||!row.data?.criteria)throw Error('저장된 교정일지 형식을 확인할 수 없습니다.');S.row=row;S.year=annualYear(row);S.draft={id:row.id,calibration_year:S.year,calibration_date:S.year+'-01-01',calibration_end_date:S.year+'-12-31',operator:row.operator,reviewer:row.reviewer||'',balance_code:row.balance_code,thermometer_code:row.thermometer_code,items:clone(row.data.items).map(item=>({...item,calibration_date:''})),criteria:clone(row.data.criteria)};S.baseline=JSON.stringify(S.draft);S.request=null;S.files.clear();S.selected=S.draft.items.find(x=>x.id===selected)?.id||S.draft.items.find(x=>x.kind==='부피플라스크'&&Number(x.nominal)===100)?.id||S.draft.items[0]?.id;}
  function setupNew(items,year=S.year||new Date().getFullYear()){window.DF_QI_CAL_QUERY?.close();S.checked.clear();S.deletion=null;S.batch=null;clearImport();clearCalculations();S.page=1;revokeAll();S.row=null;S.draft=fresh(items,year);S.year=year;S.baseline=JSON.stringify(S.draft);S.request=null;S.selected=S.draft.items.find(x=>x.kind==='부피플라스크'&&Number(x.nominal)===100)?.id||S.draft.items[0]?.id;}
  function discard(){return !S.busy&&(!dirty()||confirm('저장하지 않은 교정값과 사진을 닫을까요?'))&&window.DF_QI_CAL_DOCS?.canLeave()!==false;}
  async function switchYear(value){try{context();if(S.busy)return false;const year=Number(value);if(!Number.isInteger(year)||year<2000||year>2100)throw Error('관리연도는 2000~2100년으로 입력해주세요.');if(annualYear(S.draft)===year){renderYearOptions();return true;}let found=S.history.find(row=>annualYear(row)===year);if(!found){const token=stamp();setBusy(true);try{const list=await result(context(token).rpc('df_qi_calibration_list_v378',{p_year:null}));context(token);S.history=list.rows||[];found=S.history.find(row=>annualYear(row)===year);}finally{if(S.epoch===token.epoch)setBusy(false);}}if(found){const opened=await loadRecord(found.id,{showAll:true});if(!opened)renderYearOptions();return opened;}if(!can('create')){renderYearOptions();throw Error('연도 추가 권한이 없습니다.');}if(!discard()){renderYearOptions();return false;}const items=S.draft?.items;S.epoch++;setupNew(items,year);S.ready=true;S.kind='all';S.capacity='all';S.query='';$('search').value='';render();say('');return true;}catch(e){if(S.draft)renderYearOptions();throw e;}}
  async function startNew(value){context();if(!can('create'))throw Error('교정일지 작성 권한이 없습니다.');if(Number.isInteger(value))return switchYear(value);$('newYear').value=String(annualYear(S.draft)+1);$('newYear').setCustomValidity('');$('newYearDialog').showModal();applyPermission();}
  async function attachPhoto(itemId,index,file){if(!file)return;const token=stamp();context(token);if(!writable()||!can('upload'))throw Error('사진 업로드 권한이 없습니다.');if(!file.name?.trim()||file.name.length>255)throw Error('사진 파일명은 1~255자로 지정해주세요.');if(!/^image\/(jpeg|png|webp|avif)$/.test(file.type)||file.size<1||file.size>20*1024*1024)throw Error('JPG·PNG·WebP·AVIF 사진을 20MB 이내로 선택해주세요.');setBusy(true);try{const hash=await sha(file);context(token);const ext={'image/jpeg':'jpg','image/png':'png','image/webp':'webp','image/avif':'avif'}[file.type],id=uid(),item=S.draft.items.find(x=>x.id===itemId);if(!item)throw Error('초자를 다시 선택해주세요.');const preview=URL.createObjectURL(file);try{const img=new Image();await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=()=>reject(Error('사진을 표시할 수 없습니다. JPG·PNG로 다시 선택해주세요.'));img.src=preview;});}finally{URL.revokeObjectURL(preview);}context(token);const meta={id,path:`${token.identity}/${S.draft.id}/${id}.${ext}`,name:file.name,mime:file.type,size:file.size,sha256:hash};item.photos[index]=meta;S.files.set(id,{file,meta,uploaded:false});S.blobs.set(id,file);modified();renderPhotos();say('');}finally{if(S.epoch===token.epoch)setBusy(false);}}
  function payload(){return {calibration_year:annualYear(S.draft),operator:S.draft.operator,reviewer:S.draft.reviewer,balance_code:S.draft.balance_code,thermometer_code:S.draft.thermometer_code,items:clone(S.draft.items).map(item=>({...item,calibration_date:item.calibration_date??''}))};}
  async function save(){const token=stamp();context(token);if(!writable())throw Error('교정일지 저장 권한이 없습니다.');const year=annualYear(S.draft);if(!Number.isInteger(year)||year<2000||year>2100)throw Error('관리연도를 확인해주세요.');const validation=M().validateSession(S.draft);if(!validation.ok){const issue=validation.errors[0];if(issue.itemId){S.kind='all';S.query='';$('search').value='';S.selected=issue.itemId;renderRows();renderDetail();}throw Error(issue.message||'입력값을 확인해주세요.');}const data=payload(),serial=JSON.stringify(data);if(!S.request||S.request.serial!==serial)S.request={id:uid(),serial,data,version:S.row?.lock_version??null,sessionId:S.draft.id};const request=S.request;setBusy(true);say('저장 중…');try{for(const item of request.data.items)for(const meta of item.photos.filter(Boolean)){const pending=S.files.get(meta.id);if(!pending||pending.uploaded)continue;if(!can('upload'))throw Error('사진 업로드 권한이 없습니다.');const response=await context(token).storage.from(BUCKET).upload(meta.path,pending.file,{contentType:meta.mime,upsert:false});if(response.error){if(String(response.error.statusCode||response.error.status)!=='409'&&!/already exists|duplicate/i.test(response.error.message||''))throw response.error;const existing=await result(context(token).storage.from(BUCKET).download(meta.path));context(token);if(existing.size!==meta.size||await sha(existing)!==meta.sha256)throw Error('동일 사진 경로의 원본이 다릅니다.');}context(token);pending.uploaded=true;}const answer=await result(context(token).rpc('df_qi_calibration_save_v378',{p_id:request.sessionId,p_version:request.version,p_data:request.data,p_request_id:request.id}));context(token);accept(answer.session);S.history=[...S.history.filter(row=>row.id!==S.row.id),S.row].sort((a,b)=>annualYear(b)-annualYear(a));render();say('저장했습니다.');}finally{if(S.epoch===token.epoch){setBusy(false);applyPermission();}}}
  function renderHistory(){const filter=$('historyYear').value,rows=S.history.filter(row=>filter==='all'||annualYear(row)===Number(filter));$('historyBody').innerHTML=rows.length?'<div class="history-list">'+rows.map(row=>`<div class="annual-history-entry"><button type="button" class="history-row" data-history="${esc(row.id)}"><span class="history-date">${annualYear(row)}년</span><span><strong>초자내부교정일지</strong><small>담당자 ${esc(row.operator)||'—'} · 검토자 ${esc(row.reviewer)||'—'}</small></span>${svg('chevron')}</button>${can('delete')?`<button type="button" class="history-delete" data-archive="${esc(row.id)}" aria-label="${annualYear(row)}년 일지 삭제">${svg('trash')}</button>`:''}</div>`).join('')+'</div>':'<div class="empty-state">저장된 연도별 일지가 없습니다.</div>';}
  async function history(){const token=stamp();context(token);if(S.busy||!S.ready)return;setBusy(true);try{const list=await result(context(token).rpc('df_qi_calibration_list_v378',{p_year:null}));context(token);S.history=list.rows||[];const selected=$('historyYear').value||'all';$('historyYear').innerHTML='<option value="all">전체 연도</option>'+[...new Set(S.history.map(annualYear))].sort((a,b)=>b-a).map(year=>`<option value="${year}">${year}년</option>`).join('');$('historyYear').value=[...$('historyYear').options].some(option=>option.value===selected)?selected:'all';renderHistory();$('historyDialog').showModal();}finally{if(S.epoch===token.epoch)setBusy(false);}}
  async function loadRecord(id,options={}){if(!discard())return false;const token=stamp();context(token);setBusy(true);say('');try{const row=await result(context(token).rpc('df_qi_calibration_get_v368',{p_id:id}));context(token);revokeAll();S.epoch++;accept(row);S.ready=true;if(options.showAll){S.kind='all';S.capacity='all';S.query='';$('search').value='';if(options.itemId&&S.draft.items.some(x=>x.id===options.itemId))S.selected=options.itemId;}$('historyDialog').close();render();return true;}finally{if(S.active&&me()?.id===token.identity&&db()===token.client)setBusy(false);}}
  async function archive(id){const row=S.history.find(x=>x.id===id);if(!row||S.busy)return;const token=stamp();context(token);if(!can('delete'))throw Error('교정일지 삭제 권한이 없습니다.');if(id===S.row?.id&&!discard())return;if(!confirm(`${periodText(row)} 교정일지를 목록에서 삭제할까요? 원본 이력은 보관됩니다.`))return;setBusy(true);try{await result(context(token).rpc('df_qi_calibration_archive_v368',{p_id:id,p_version:row.lock_version,p_request_id:uid()}));context(token);if(S.row?.id===id){const year=annualYear(S.row);S.epoch++;setupNew(S.row.data.items,year);S.history=S.history.filter(item=>item.id!==id);render();}say('목록에서 삭제했습니다.');}finally{if(S.active&&me()?.id===token.identity)setBusy(false);}await history();}
  function printMarkup(){const shown=visible(),rows=shown.map((item,index)=>{const r=calculate(item);return `<tr><td>${index+1}</td><td class="print-item"><strong>${esc(item.name)}</strong><br><small>${esc(item.code)}</small></td><td>${esc(item.beta)}</td><td>${esc(item.m1)||'—'}</td><td>${esc(item.m2)||'—'}</td><td>${fmt(r.mass)}</td><td>${esc(item.temp)||'—'}</td><td>${fmt(r.rho,6)}</td><td>${fmt(r.volume)}</td><td>${item.tolerance===''?'—':'±'+esc(item.tolerance)}</td><td>${fmt(r.error)}</td><td>${esc(r.label)}</td><td class="print-note">${esc(item.note||'').replace(/\n/g,'<br>')}</td></tr>`;}).join('');const photos=shown.filter(x=>x.photos.some(Boolean));return `<article class="print-sheet"><div class="print-top"><span>DREAMFOREN</span><span>${CODE} (00)${dirty()||!S.row?' · 작성 중':''}</span></div><h1>초자내부교정일지</h1><div class="print-meta"><span>관리연도 <b>${esc(periodText(S.draft))}</b></span><span>담당자 <b>${esc(S.draft.operator)||'—'}</b></span><span>사용 저울 <b>${esc(S.draft.balance_code)||'—'}</b></span><span>온도계 <b>${esc(S.draft.thermometer_code)||'—'}</b></span></div><table class="print-table"><thead><tr>${['No.','초자 / 관리번호','팽창계수','M1 (g)','M2 (g)','질량 (g)','수온 (℃)','물의 밀도','20℃ 부피 (mL)','허용오차','실측오차','판정','비고'].map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows}</tbody></table><div class="print-sign"><span>점검자 <b>${esc(S.draft.operator)}</b> (서명)</span><span>검토자 <b>${esc(S.draft.reviewer)||'__________________'}</b> (서명)</span></div><footer class="print-footer">주식회사 드림포이엔 <span>기준온도 20℃ · 실측오차 = 정격부피 − 환산부피</span></footer></article>${photos.map(item=>`<article class="print-sheet photo-sheet"><div class="print-top"><span>DREAMFOREN</span><span>${CODE} (00)</span></div><h1>교정 사진</h1><div class="print-meta"><span>${esc(item.name)} · ${esc(item.code)}</span><span>관리연도 ${esc(periodText(S.draft))}</span></div><div class="print-photo-grid">${['측정 전','측정 후'].map((caption,index)=>`<figure><figcaption>${caption}</figcaption>${item.photos[index]?`<img src="${urlFor(item.photos[index].id,S.blobs.get(item.photos[index].id))}" alt="${caption}">`:'<div class="print-photo-empty">—</div>'}</figure>`).join('')}</div></article>`).join('')}`;}
  async function previewPrint(){const token=stamp();context(token);if(!visible().length)throw Error('현재 용량에 표시할 초자가 없습니다.');setBusy(true);try{await Promise.all(visible().flatMap(x=>x.photos.filter(Boolean)).map(meta=>photoBlob(meta,token)));context(token);$('printContent').innerHTML=printMarkup();$('printDialog').showModal();}finally{if(S.epoch===token.epoch)setBusy(false);}}
  function printNow(){context();const w=window.open('','_blank');if(!w)throw Error('팝업 차단을 해제해주세요.');S.printWindows.push(w);w.document.write(`<!doctype html><html lang="ko"><head><meta charset="utf-8"><title>초자내부교정일지</title><style>@page{size:A4 landscape;margin:12mm}*{box-sizing:border-box}body{font:10pt/1.45 "Malgun Gothic",sans-serif;color:#223a44;margin:0}nav{padding:12px;position:sticky;top:0;background:#fff}button{padding:8px 18px}h1{text-align:center;font-size:19pt;margin:12px 0 20px}.print-top,.print-meta,.print-footer,.print-sign{display:flex;justify-content:space-between;gap:16px;font-size:9pt;margin:12px 0}.print-top{color:#607887}.print-table{width:100%;border-collapse:collapse;font-size:8pt}th,td{border:1px solid #9caab1;padding:6px 3px;text-align:center}th{background:#f1f5f5}.print-item,.print-note{text-align:left;overflow-wrap:anywhere}.print-note{max-width:35mm;white-space:normal}small{font-size:7pt}.print-sign{justify-content:flex-end;gap:50px}.photo-sheet{break-before:page}.print-photo-grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}figure{margin:0}figcaption{text-align:center;margin:12px}img,.print-photo-empty{width:100%;height:125mm;object-fit:contain;border:1px solid #adbcc4}.print-sheet{break-after:page}.print-sheet:last-child{break-after:auto}thead{display:table-header-group}tr{break-inside:avoid}@media print{nav{display:none}}</style></head><body><nav><button id="qiPrintButton">인쇄 / PDF 저장</button></nav>${$('printContent').innerHTML}</body></html>`);w.document.close();w.document.getElementById('qiPrintButton').onclick=()=>w.print();}
  function quantityItems(){const count=Number($('newQuantity').value),code=$('newCode').value.trim(),room=500-S.draft.items.length;if(!Number.isInteger(count)||count<1||count>room)throw Error(`추가 수량은 1~${Math.max(0,room)}개입니다.`);if(!code||code.length>60)throw Error('시작 관리번호를 입력해주세요.');const match=code.match(/^(.*?)(\d+)$/);if(count>1&&!match)throw Error('여러 개를 추가할 때는 관리번호 끝에 순번을 넣어주세요.');const codes=[];for(let i=0;i<count;i++){let next=code;if(count>1){const number=Number(match[2])+i;if(!Number.isSafeInteger(number))throw Error('관리번호 순번이 너무 큽니다.');next=match[1]+String(number).padStart(match[2].length,'0');}if(next.length>60||S.draft.items.some(x=>x.code.trim()===next))throw Error(`이미 등록되었거나 사용할 수 없는 관리번호: ${next}`);codes.push(next);}return codes;}
  function quantityPreview(){$('newCode').setCustomValidity('');$('newQuantity').setCustomValidity('');try{const codes=quantityItems();$('newRange').textContent=codes.length===1?codes[0]:codes[0]+' ~ '+codes[codes.length-1];}catch(e){$('newRange').textContent=e.message;}}
  function addMany(){context();if(!writable())return;let codes;try{codes=quantityItems();}catch(e){$('newQuantity').setCustomValidity(e.message);$('newQuantity').reportValidity();return;}const base=M().newItem(selectedType(),S.draft.items),items=codes.map((code,i)=>({...clone(base),id:i?uid():base.id,code}));S.draft.items.push(...items);S.selected=items[0].id;S.kind=base.kind;S.capacity=capacityKey(base.nominal);S.capacityMemory[base.kind]=S.capacity;S.query='';$('search').value='';modified();renderRows();renderDetail();$('addDialog').close();say(`${items.length}개를 추가했습니다.`);}
  function clearImport(){S.importSeq++;S.importController?.abort();S.importController=null;S.importing=false;S.importParsed=null;S.importPlan=null;S.importTarget=null;S.importBase='';S.importSelection.clear();S.importBlocked='';S.importPage=1;}
  function cancelImport(){const wasReading=S.importing;clearImport();$('importDialog')?.close();if(wasReading&&S.active)setBusy(false);}
  function openImport(){context();if(!writable()||!can('upload'))throw Error('엑셀 불러오기 권한이 없습니다.');clearImport();$('importReview').hidden=true;$('importStatus').textContent='';$('importFilename').textContent='또는 파일 끌어놓기 · XLSX / XLS';$('importDialog').showModal();applyPermission();}
  async function readImport(file){context();if(!writable()||!can('upload'))return;if(!window.DF_QI_CAL_IMPORT_IO||!window.DF_QI_CAL_IMPORT)throw Error('엑셀 불러오기 파일을 새로고침해주세요.');clearImport();const seq=S.importSeq,token=stamp();S.importing=true;S.importController=new AbortController();S.importBase=JSON.stringify(S.draft);$('importFilename').textContent=file.name;$('importReview').hidden=true;$('importStatus').textContent='엑셀을 읽는 중…';if(!$('importDialog').open)$('importDialog').showModal();setBusy(true);try{const parsed=await window.DF_QI_CAL_IMPORT_IO.read(file,{annualMode:true,signal:S.importController.signal,onProgress(p){if(seq===S.importSeq&&S.epoch===token.epoch)$('importStatus').textContent=p.phase==='parsing'?'입력 내용을 확인하는 중…':'엑셀을 읽는 중…';}});context(token);if(seq!==S.importSeq)return;S.importParsed=parsed;if(!parsed.rows?.length){$('importStatus').textContent=parsed.errors?.map(x=>x.message).join(' ')||'가져올 입력값이 없습니다.';return;}refreshImportPlan();$('importReview').hidden=false;$('importStatus').textContent=parsed.errors?.length?`파일 확인 필요 ${parsed.errors.length}건 · 해당 행은 반영되지 않습니다.`:'불러올 항목을 확인해주세요.';}catch(e){if(seq!==S.importSeq||e.name==='AbortError')return;if(e.code==='QI_CONTEXT_CHANGED'){error(e);return;}$('importStatus').textContent=e.message||'엑셀을 읽지 못했습니다.';}finally{if(seq===S.importSeq&&S.epoch===token.epoch){S.importing=false;S.importController=null;setBusy(false);renderImportRows();}}}
  function refreshImportPlan(){if(!S.importParsed)return;S.importTarget=clone(S.draft);const rows=S.importParsed.rows.map(row=>({...row,date:''}));S.importBlocked=S.importParsed.errors?.some(error=>['rows','sheets','workbook'].includes(error.field))?'파일의 전체 행·시트 범위를 확인해주세요. 자료를 나누어 다시 불러와주세요.':'';S.importPlan=window.DF_QI_CAL_IMPORT.plan(rows,S.importTarget.items,S.importTarget.criteria);S.importSelection=new Set(S.importPlan.candidates.filter(importCandidateEligible).map(candidate=>candidate.index));S.importPage=1;$('importWarnings').textContent=(S.importParsed.warnings||[]).filter(warning=>warning.field!=='date').map(warning=>warning.message).join(' ');renderImportRows();}
  function activeImportPlan(){return S.importPlan;}
  function importCandidateEligible(candidate){return !!candidate&&['add','fill'].includes(candidate.action);}
  function importWriteAllowed(){return writable()&&can('view')&&can('upload');}
  function importReady(){if(!S.importPlan||S.importBlocked||!S.importSelection.size||!importWriteAllowed())return false;const chosen=S.importPlan.candidates.filter(candidate=>S.importSelection.has(candidate.index)&&importCandidateEligible(candidate));return chosen.length===S.importSelection.size&&!(S.importPlan.errors||[]).some(error=>error.field!=='items')&&S.draft.items.length+chosen.filter(candidate=>candidate.action==='add').length<=500;}
  function renderImportSelection(){if(!$('importApply'))return;const candidates=S.importPlan?.candidates||[],eligible=candidates.filter(importCandidateEligible),safe=new Set(eligible.map(candidate=>candidate.index)),allowed=importWriteAllowed();S.importSelection=new Set([...S.importSelection].filter(index=>safe.has(index)));const selected=S.importSelection.size;$('importBody').querySelectorAll('[data-import-index]').forEach(el=>{const index=Number(el.dataset.importIndex);el.checked=S.importSelection.has(index);el.disabled=!allowed||!!S.importBlocked||!safe.has(index);});$('importAll').checked=eligible.length>0&&selected===eligible.length;$('importAll').indeterminate=selected>0&&selected<eligible.length;$('importAll').disabled=!allowed||!!S.importBlocked||!eligible.length;$('importApply').disabled=!importReady();$('importSelected').textContent=`${selected}개 선택 · 반영 가능 ${eligible.length}개`;$('importYear').textContent=annualYear(S.draft)+'년 일지에 반영';if(S.importPlan){const sum=S.importPlan.summary;$('importSummary').textContent=`추가 ${sum.add} · 채움 ${sum.fill} · 동일 ${sum.skip} · 확인 ${sum.conflict}`;}let hint=S.importBlocked||'';if(!hint&&S.importPlan){if(!eligible.length)hint=candidates.length&&candidates.every(candidate=>candidate.action==='skip')?'모든 항목이 이미 저장되어 있습니다.': '반영 가능한 항목이 없습니다. 각 행의 확인 사유를 확인해주세요.';else if(!selected)hint='반영할 항목을 선택해주세요.';else if(!importReady()&&!S.busy)hint=allowed?'연도별 일지당 500개 이내로 선택해주세요.':'항목 반영 권한을 확인해주세요.';}$('importEligibility').textContent=hint;$('importEligibility').hidden=!hint;const pages=Math.max(1,Math.ceil(candidates.length/50));$('importPrev').disabled=S.busy||S.importPage<=1;$('importNext').disabled=S.busy||S.importPage>=pages;}
  function renderImportRows(){if(!S.importPlan){renderImportSelection();return;}const all=S.importPlan.candidates,pages=Math.max(1,Math.ceil(all.length/50));S.importPage=Math.max(1,Math.min(S.importPage,pages));$('importBody').innerHTML=all.slice((S.importPage-1)*50,S.importPage*50).map(candidate=>{const item=candidate.item||candidate.row;return `<tr class="import-${esc(candidate.action)}"><td><input type="checkbox" data-import-index="${candidate.index}" aria-label="${esc(item.code)} 선택" disabled></td><td><span class="import-tag">${({add:'추가',fill:'채움',skip:'동일',conflict:'확인'})[candidate.action]}</span></td><td><strong>${esc(item.name||item.kind+' '+item.nominal+' mL')}</strong><small>${esc(item.code)}${candidate.codeInferred?' · 번호 확인':''}</small></td><td>${esc(item.m1)||'—'}</td><td>${esc(item.m2)||'—'}</td><td>${esc(item.temp)||'—'}</td><td class="import-reason">${esc(candidate.reason)}<small>${esc(candidate.source?.sheet)} ${esc(candidate.source?.row)}행</small></td></tr>`;}).join('');$('importPage').textContent=`${S.importPage} / ${pages}`;renderImportSelection();}
  function applyImport(){context();renderImportSelection();if(!importReady())return;if(S.importBase!==JSON.stringify(S.draft))throw Error('일지 입력이 변경되었습니다. 파일을 다시 불러와주세요.');const chosen=S.importPlan.candidates.filter(candidate=>S.importSelection.has(candidate.index)&&importCandidateEligible(candidate)),check=window.DF_QI_CAL_IMPORT.plan(chosen.map(candidate=>candidate.row),S.draft.items,S.draft.criteria);if(!check.ok||check.summary.conflict)throw Error('반영할 항목과 기존 자료를 다시 확인해주세요.');const draft=clone(S.draft);for(const candidate of check.candidates){if(candidate.action==='fill')draft.items[candidate.existingIndex]=clone(candidate.item);else if(candidate.action==='add')draft.items.push(clone(candidate.item));}const changed=check.candidates.find(candidate=>['add','fill'].includes(candidate.action));if(!changed)return;clearCalculations();S.draft=draft;S.request=null;S.selected=changed.item.id;const groups=new Set(check.candidates.map(candidate=>candidate.row.kind+'|'+capacityKey(candidate.row.nominal)));S.kind=groups.size>1?'all':changed.item.kind;S.capacity=S.kind==='all'?'all':capacityKey(changed.item.nominal);if(S.kind!=='all')S.capacityMemory[S.kind]=S.capacity;S.query='';$('search').value='';const count=check.summary.add+check.summary.fill;clearImport();$('importDialog').close();modified();render();say(`${count}개를 ${annualYear(S.draft)}년 일지에 반영했습니다. 저장해주세요.`);}

  function batchScope(){return [S.kind==='all'?'전체 초자':S.kind,S.kind==='all'?'전체 용량':S.capacity+' mL',S.query?'검색: '+S.query:''].filter(Boolean).join(' · ');}
  function openBatchCriteria(){context();if(!writable())return;const items=visible(),eligible=[],excluded=[],groups=new Map();let confirmed=0;for(const item of items){const answer=M().confirmCriteria(item);if(!answer.ok){excluded.push({code:item.code,reason:answer.errors.map(x=>x.message).join(' ')});continue;}if(item.criteriaConfirmed){confirmed++;continue;}eligible.push(item.id);const key=JSON.stringify([item.kind,capacityKey(item.nominal),item.material,item.beta,item.tolerance,item.mode]);if(!groups.has(key))groups.set(key,{item,count:0});groups.get(key).count++;}S.batch={token:stamp(),draft:S.draft,snapshot:JSON.stringify(S.draft),scopeIds:JSON.stringify(items.map(x=>x.id)),eligible};$('batchScope').textContent=batchScope()+' · 전체 페이지 '+items.length+'개';$('batchSummary').innerHTML=`<span>확인 가능 <b>${eligible.length}</b></span><span>이미 확인 <b>${confirmed}</b></span><span>제외 <b>${excluded.length}</b></span>`;$('batchGroups').innerHTML=groups.size?`<table><thead><tr><th>초자</th><th>재질</th><th>팽창계수</th><th>허용오차 (mL)</th><th>수량</th></tr></thead><tbody>${[...groups.values()].map(({item,count})=>`<tr><td>${esc(item.name)}<small>${esc(item.mode)}</small></td><td>${esc(item.material)}</td><td>${esc(item.beta)}</td><td>± ${esc(item.tolerance)}</td><td>${count}개</td></tr>`).join('')}</tbody></table>`:'<p class="batch-empty">새로 확인할 수 있는 항목이 없습니다.</p>';$('batchExcluded').innerHTML=excluded.length?`<details class="batch-excluded"><summary>기준 미입력·오류 ${excluded.length}개 제외</summary><ul>${excluded.slice(0,50).map(x=>`<li><strong>${esc(x.code)}</strong> ${esc(x.reason)}</li>`).join('')}</ul>${excluded.length>50?`<p>외 ${excluded.length-50}개</p>`:''}</details>`:'';$('batchStatus').textContent='';$('batchApply').textContent=eligible.length+'개 기준 확인';$('batchDialog').showModal();paintIcons($('batchDialog'));applyPermission();}
  function applyBatchCriteria(){const plan=S.batch;if(!plan)return;context(plan.token);if(!writable())return;if(plan.draft!==S.draft||plan.snapshot!==JSON.stringify(S.draft)||plan.scopeIds!==JSON.stringify(visible().map(x=>x.id))){$('batchStatus').textContent='입력 내용이 변경되었습니다. 닫고 다시 확인해주세요.';return;}const wanted=new Set(plan.eligible),items=S.draft.items.filter(x=>wanted.has(x.id));if(items.length!==wanted.size||items.some(x=>!M().confirmCriteria(x).ok)){$('batchStatus').textContent='교정 기준을 다시 확인해주세요.';return;}if(!items.length)return;for(const item of items)item.criteriaConfirmed=true;S.batch=null;$('batchDialog').close();modified();renderRows();refreshResult();say(items.length+'개 기준을 확인했습니다. 일지를 저장해주세요.');}
  function renderDeleteSelection(){const shown=visible(),selected=shown.filter(x=>S.checked.has(x.id)).length;$('selectAll').checked=shown.length>0&&selected===shown.length;$('selectAll').indeterminate=selected>0&&selected<shown.length;$('deleteSelected').textContent=selected?'선택 삭제 ('+selected+')':'선택 삭제';$('itemsBody').querySelectorAll('[data-delete-id]').forEach(x=>x.checked=S.checked.has(x.dataset.deleteId));applyPermission();}
