  function ensure(){if(root())return;if(!window.DF_QPF_FORMS||!M()||!D())throw Error('교정일지 파일을 새로고침해주세요.');const parent=document.getElementById('dfQualityFormWorkspace');if(!parent)throw Error('작성용 품질문서 폴더를 먼저 열어주세요.');const pane=document.createElement('section');pane.id='qiCalibrationPane';pane.hidden=true;pane.innerHTML=MARKUP;parent.append(pane);paintIcons();const year=new Date().getFullYear();$('historyYear').innerHTML='<option value="all">전체 연도</option>'+Array.from({length:21},(_,i)=>year+1-i).map(x=>`<option value="${x}">${x}년</option>`).join('');bind();}
  function openDocuments(){window.DF_QI_CAL_DOCS?.open({parent:root(),getContext:()=>({actor:me()?.id,client:db(),active:S.active,can})}).catch(()=>{});}
